package pe.vichaval.gestionriego.caja.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import pe.vichaval.gestionriego.usuario.entity.Usuario;@Entity@Table(name="cierres_caja")public class CierreCaja{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private LocalDate fecha;@Column(name="saldo_inicial")private BigDecimal saldoInicial;private BigDecimal ingresos;private BigDecimal egresos;private BigDecimal devoluciones;@Column(name="saldo_teorico")private BigDecimal saldoTeorico;@Column(name="saldo_contado")private BigDecimal saldoContado;private BigDecimal diferencia;private String observaciones;private String estado="CERRADO";@ManyToOne@JoinColumn(name="usuario_id")private Usuario usuario;protected CierreCaja(){}public CierreCaja(LocalDate f,BigDecimal si,BigDecimal i,BigDecimal e,BigDecimal d,BigDecimal sc,String o,Usuario u){fecha=f;saldoInicial=si;ingresos=i;egresos=e;devoluciones=d;saldoTeorico=si.add(i).subtract(e).subtract(d);saldoContado=sc;diferencia=sc.subtract(saldoTeorico);observaciones=o;usuario=u;}public Long getId(){return id;}public LocalDate getFecha(){return fecha;}public BigDecimal getSaldoTeorico(){return saldoTeorico;}public BigDecimal getSaldoContado(){return saldoContado;}public BigDecimal getDiferencia(){return diferencia;}public String getEstado(){return estado;}}
